/**
 * La autorización canónica de una ejecución local gestionada (ADR-THYROX-007,
 * enmienda 1.16.0).
 *
 * Todo trabajo local que thyrox gestiona —crear un banco, escribir o editar
 * archivos, instalar dependencias, compilar, probar, sondear, servir o
 * cuantizar un modelo, commitear— corre dentro de un contenedor de ejecución
 * que esta primitiva materializa. El anfitrión es plano de control: compone la
 * autorización, la entrega aquí y observa el resultado.
 *
 * La autorización es la del contenedor. Una decisión de dominio la COMPONE,
 * no la hereda: un `ExecutionGrant` de modelo (model-artifacts) se traduce en
 * una autorización `model-runtime` con referencia al grant; este paquete es
 * neutral y no conoce modelos. La identidad de un runtime de modelo ya
 * materializado es la `ExecutionUnit` de model-scheduling.
 *
 * El repositorio puede montarse de escritura: la mutación llega al árbol real,
 * pero el proceso que la hace vive en el contenedor, no en el shell que la
 * pidió.
 */

import { inspectContainerState, materializeContainer, runJobWithOutput, type JobOutput } from './containerRun.js'
import type { PodmanExecutor } from './podmanExecutor.js'
import { requireValidOwner, type ContainerOwner, type WorkerContainerSpec } from './workerContainerLifecycle.js'
import {
  InvalidWorkerResourceProfileError,
  workerResourceLimitArgv,
  type WorkerNetworkMode,
  type WorkerPublishedPort,
  type WorkerResourceMount,
} from './workerResourceProfile.js'

export const EXECUTION_KINDS = [
  'workbench',
  'build',
  'test',
  'probe',
  'infrastructure',
  'model-runtime',
  'quantization',
  'registry-operation',
  'maintenance',
] as const

export type ExecutionKind = (typeof EXECUTION_KINDS)[number]

export const EXECUTION_KIND_LABEL_KEY = 'thyrox.execution-kind'
export const EXECUTION_REFERENCE_LABEL_KEY = 'thyrox.execution-reference'
export const EXECUTION_ID_LABEL_KEY = 'thyrox.execution-id'
const EXECUTION_LABEL_KEYS = [EXECUTION_KIND_LABEL_KEY, EXECUTION_REFERENCE_LABEL_KEY, EXECUTION_ID_LABEL_KEY]

/** La cita durable de una tarea; el ordinal del board reinicia por sesión y no identifica nada. */
export const TASK_CITATION_PATTERN = /^TASK-[A-Z]+-\d{4}$/
const EXECUTION_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,62}$/
const REFERENCE_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_.:-]*$/
const SECRET_NAME_PATTERN = /^[a-z0-9][a-z0-9_.-]*$/
const SECRET_TARGET_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_.-]*$/

/** Lo que autoriza la ejecución: la tarea, el grant de modelo o el recurso de infraestructura. */
export type ExecutionReference =
  | { kind: 'task'; citation: string }
  | { kind: 'grant'; grantId: string }
  | { kind: 'infrastructure'; resource: string }

export type ExecutionResources = {
  cpus: number
  memoryMib: number
  pidsLimit: number
}

/** Un secreto de Podman por su nombre; se monta como archivo, su valor nunca pasa por aquí. */
export type ExecutionSecret = {
  name: string
  target: string
}

export type ExecutionAuthorization = {
  /** Nombra el contenedor (`thyrox-worker-<executionId>`). */
  executionId: string
  reference: ExecutionReference
  owner: ContainerOwner
  kind: ExecutionKind
  image: string
  /** Sin comando, el de la imagen. */
  command?: readonly string[]
  /** Sin directorio, el de la imagen; declarado, vive dentro de un montaje. */
  workdir?: string
  mounts: readonly WorkerResourceMount[]
  resources: ExecutionResources
  network: WorkerNetworkMode
  /** Sólo valores públicos: quedan en `podman inspect`. */
  environment?: Readonly<Record<string, string>>
  secrets?: readonly ExecutionSecret[]
  publishedPorts?: readonly WorkerPublishedPort[]
  /** Dispositivos en forma CDI. */
  devices?: readonly string[]
  /** Etiquetas propias del dueño; no reescriben las de la ejecución. */
  labels?: Readonly<Record<string, string>>
  /** Rutas que el trabajo produce; cada una bajo un montaje de escritura. */
  outputs?: readonly string[]
  /** Instante, en milisegundos Unix, a partir del cual la autorización no vale. */
  expiresAt?: number
}

/** La autorización no se puede materializar; nombra el campo. */
export class InvalidExecutionAuthorizationError extends Error {
  readonly field: string

  constructor(field: string, message: string) {
    super(message)
    this.name = 'InvalidExecutionAuthorizationError'
    this.field = field
  }
}

function refuse(field: string, message: string): never {
  throw new InvalidExecutionAuthorizationError(field, message)
}

function isUnder(path: string, root: string): boolean {
  const prefix = root.endsWith('/') ? root : `${root}/`
  return path === root || path.startsWith(prefix)
}

function isKnownKind(kind: string): kind is ExecutionKind {
  return (EXECUTION_KINDS as readonly string[]).includes(kind)
}

/** El tipo de referencia que cada tipo de ejecución exige. */
function expectedReferenceKind(kind: ExecutionKind): ExecutionReference['kind'] {
  if (kind === 'model-runtime') return 'grant'
  if (kind === 'infrastructure') return 'infrastructure'
  return 'task'
}

function referenceLabel(reference: ExecutionReference): string {
  if (reference.kind === 'task') return `task:${reference.citation}`
  if (reference.kind === 'grant') return `grant:${reference.grantId}`
  return `infrastructure:${reference.resource}`
}

function requireReference(kind: ExecutionKind, reference: ExecutionReference): void {
  const expected = expectedReferenceKind(kind)
  if (reference.kind !== expected) refuse('reference', `una ejecución ${kind} se autoriza por ${expected}, recibido: ${reference.kind}`)
  if (reference.kind === 'task' && !TASK_CITATION_PATTERN.test(reference.citation)) {
    refuse('reference', `la tarea se cita como TASK-<CAPA>-NNNN, recibido: ${reference.citation}`)
  }
  const identifier = referenceLabel(reference).slice(reference.kind.length + 1)
  if (!REFERENCE_ID_PATTERN.test(identifier)) refuse('reference', `identificador de referencia inválido: ${identifier}`)
}

function requireOwner(owner: ContainerOwner): void {
  try {
    requireValidOwner(owner)
  } catch (error) {
    refuse('owner', error instanceof Error ? error.message : String(error))
  }
}

function requireWorkdir(authorization: ExecutionAuthorization): void {
  const { workdir } = authorization
  if (workdir === undefined) return
  if (!authorization.mounts.some(mount => isUnder(workdir, mount.destination))) {
    refuse('workdir', `el directorio de trabajo ${workdir} no vive dentro de ningún montaje`)
  }
}

function requireOutputsWritable(authorization: ExecutionAuthorization): void {
  for (const output of authorization.outputs ?? []) {
    const writable = authorization.mounts.some(mount => mount.mode === 'rw' && isUnder(output, mount.destination))
    if (!writable) refuse('outputs', `la salida ${output} no vive bajo un montaje de escritura`)
  }
}

function requireSecretsByName(secrets: readonly ExecutionSecret[]): void {
  secrets.forEach((secret, index) => {
    if (!SECRET_NAME_PATTERN.test(secret.name)) refuse(`secrets[${index}].name`, `nombre de secreto inválido: ${secret.name}`)
    if (!SECRET_TARGET_PATTERN.test(secret.target)) refuse(`secrets[${index}].target`, `destino de secreto inválido: ${secret.target}`)
  })
}

function requireOwnLabels(labels: Readonly<Record<string, string>>): void {
  const overridden = Object.keys(labels).filter(key => EXECUTION_LABEL_KEYS.includes(key))
  if (overridden.length > 0) refuse('labels', `las etiquetas ${overridden.join(', ')} son de la ejecución, no del dueño`)
}

/** Valida la autorización completa; rehúsa en el primer campo inválido, nombrándolo. */
export function validateExecutionAuthorization(authorization: ExecutionAuthorization, now = Date.now()): void {
  if (!EXECUTION_ID_PATTERN.test(authorization.executionId)) refuse('executionId', `id de ejecución inválido: ${authorization.executionId}`)
  if (!isKnownKind(authorization.kind)) refuse('kind', `tipo de ejecución desconocido: ${authorization.kind}`)
  requireReference(authorization.kind, authorization.reference)
  requireOwner(authorization.owner)
  if (!authorization.image) refuse('image', 'la imagen no puede estar vacía')
  if (authorization.command !== undefined && !authorization.command[0]) refuse('command', 'un comando declarado no puede estar vacío')
  requireWorkdir(authorization)
  requireOutputsWritable(authorization)
  requireSecretsByName(authorization.secrets ?? [])
  requireOwnLabels(authorization.labels ?? {})
  if (authorization.expiresAt !== undefined && authorization.expiresAt <= now) refuse('expiresAt', 'la autorización expiró')
}

function resourceArgv(authorization: ExecutionAuthorization): string[] {
  try {
    return workerResourceLimitArgv({
      ...authorization.resources,
      network: authorization.network,
      readOnlyRootfs: false,
      mounts: [...authorization.mounts],
      environment: authorization.environment,
      publishedPorts: authorization.publishedPorts,
      devices: authorization.devices,
    })
  } catch (error) {
    if (error instanceof InvalidWorkerResourceProfileError) refuse(error.field, error.message)
    throw error
  }
}

function workdirArgv(workdir: string | undefined): string[] {
  return workdir === undefined ? [] : ['--workdir', workdir]
}

function secretArgv(secrets: readonly ExecutionSecret[]): string[] {
  return secrets.flatMap(secret => ['--secret', `${secret.name},type=mount,target=${secret.target}`])
}

/** Traduce una autorización válida al contenedor que la primitiva materializa. No ejecuta nada. */
export function executionContainerSpec(authorization: ExecutionAuthorization, now = Date.now()): WorkerContainerSpec {
  validateExecutionAuthorization(authorization, now)
  return {
    workerId: authorization.executionId,
    image: authorization.image,
    owner: authorization.owner,
    resourceArgv: [...resourceArgv(authorization), ...workdirArgv(authorization.workdir), ...secretArgv(authorization.secrets ?? [])],
    command: authorization.command,
    labels: {
      ...authorization.labels,
      [EXECUTION_KIND_LABEL_KEY]: authorization.kind,
      [EXECUTION_REFERENCE_LABEL_KEY]: referenceLabel(authorization.reference),
      [EXECUTION_ID_LABEL_KEY]: authorization.executionId,
    },
  }
}

/** Corre el trabajo autorizado hasta que termine y retira su contenedor; devuelve su veredicto y su diagnóstico. */
export async function runExecution(podman: PodmanExecutor, authorization: ExecutionAuthorization, now = Date.now()): Promise<JobOutput> {
  return runJobWithOutput(podman, executionContainerSpec(authorization, now))
}

/**
 * La unidad materializada: la única identidad de una ejecución gestionada,
 * cualquiera que sea su clase. Un dominio la especializa —la unidad de un
 * modelo añade su grant y su endpoint— sin definir otra.
 */
export interface ExecutionUnit {
  readonly unitId: string
  readonly kind: ExecutionKind
  readonly reference: ExecutionReference
  readonly owner: ContainerOwner
  readonly containerName: string
  readonly containerId: string
  /** El cgroup del contenedor visto desde el anfitrión, si Podman lo informa. */
  readonly cgroup?: string
  /** PIDs del proceso principal vistos desde el anfitrión; vacío si no corre. */
  readonly hostPids: readonly number[]
  /** Instante ISO 8601 en UTC. */
  readonly createdAt: string
}

/**
 * Crea, arranca e inspecciona el contenedor de una ejecución de vida larga y
 * devuelve su `ExecutionUnit`; no lo espera ni lo retira. Un fallo nombra la
 * etapa (`create`, `start`, `inspect`) y, a partir de `start`, el contenedor
 * queda creado para su dueño.
 */
export async function materializeExecution(
  podman: PodmanExecutor,
  authorization: ExecutionAuthorization,
  now = Date.now(),
): Promise<ExecutionUnit> {
  const { containerName, containerId } = await materializeContainer(podman, executionContainerSpec(authorization, now))
  const state = await inspectContainerState(podman, containerName)
  return {
    unitId: authorization.executionId,
    kind: authorization.kind,
    reference: authorization.reference,
    owner: authorization.owner,
    containerName,
    containerId,
    ...(state.cgroup === undefined ? {} : { cgroup: state.cgroup }),
    hostPids: state.hostPids,
    createdAt: new Date(now).toISOString(),
  }
}

/**
 * Correr un contenedor hasta que termine, señalarlo y exportar lo que dejó
 * (ADR-THYROX-007, TASK-THYROX-0667): la parte de «ejecutar» de la
 * primitiva, sin máquina de estados, generaciones ni recuperación — eso es
 * del dueño.
 *
 * El orden que este módulo garantiza es exportar ANTES de limpiar: `podman
 * cp` sólo lee de un contenedor que todavía existe, así que una limpieza
 * adelantada pierde el artefacto sin error visible en el llamador.
 */

import { basename, join } from 'node:path'

import type { PodmanCommandResult, PodmanExecutor } from './podmanExecutor.js'
import { isLockCollision, lockCollisionRemedy } from './podmanLockCollision.js'
import {
  createWorkerContainerArgv,
  removeWorkerContainerArgv,
  workerContainerName,
  type WorkerContainerSpec,
} from './workerContainerLifecycle.js'

export type ContainerRunStage = 'create' | 'start' | 'inspect' | 'wait' | 'logs' | 'signal' | 'export'

/** Mensaje base del fallo: la etapa, el sujeto y lo que Podman dijo. */
function failureMessage(stage: ContainerRunStage, subject: string, result: PodmanCommandResult): string {
  return `falló la etapa ${stage} sobre ${subject}: ${result.stderr.trim() || `exit ${result.exitCode}`}`
}

/**
 * Un paso de la ejecución falló; nombra la etapa y lo que Podman dijo. Si fue
 * una colisión de locks, lo marca y añade el remedio: no se reintenta en
 * silencio, porque reintentar no reasigna el lock.
 */
export class ContainerRunError extends Error {
  readonly stage: ContainerRunStage
  readonly lockCollision: boolean

  constructor(stage: ContainerRunStage, subject: string, result: PodmanCommandResult) {
    const lockCollision = isLockCollision(result.stderr)
    const message = failureMessage(stage, subject, result)
    super(lockCollision ? `${message}. ${lockCollisionRemedy(subject)}` : message)
    this.name = 'ContainerRunError'
    this.stage = stage
    this.lockCollision = lockCollision
  }
}

const EXIT_CODE_PATTERN = /^-?\d+$/

async function requireSuccess(
  podman: PodmanExecutor,
  stage: ContainerRunStage,
  subject: string,
  args: readonly string[],
): Promise<PodmanCommandResult> {
  const result = await podman.run(args)
  if (result.exitCode !== 0) throw new ContainerRunError(stage, subject, result)
  return result
}

/** Lee el código que imprime `podman wait`; una salida que no es un entero no se lee como 0. */
function parseWaitExitCode(name: string, result: PodmanCommandResult): number {
  const printed = result.stdout.trim()
  if (!EXIT_CODE_PATTERN.test(printed)) {
    throw new ContainerRunError('wait', name, { ...result, stderr: `salida de wait ilegible: «${printed}»` })
  }
  return Number(printed)
}

/** Un contenedor creado y arrancado: su nombre y el id que imprimió `podman create`. */
export type MaterializedContainer = {
  containerName: string
  containerId: string
}

/** Lo que `podman inspect` dice del contenedor en el anfitrión: su proceso y su cgroup. */
export type InspectedContainerState = {
  hostPids: readonly number[]
  cgroup?: string
}

/** Podman informa `Pid: 0` de un contenedor sin proceso. */
const NOT_RUNNING_PID = 0

/**
 * Inspecciona un contenedor y devuelve su proceso y su cgroup vistos desde el
 * anfitrión. Un fallo de Podman o una salida ilegible es la etapa `inspect`:
 * una unidad sin identidad no se publica como materializada.
 */
export async function inspectContainerState(podman: PodmanExecutor, containerName: string): Promise<InspectedContainerState> {
  const result = await podman.run(['inspect', '--format', 'json', containerName])
  if (result.exitCode !== 0) throw new ContainerRunError('inspect', containerName, result)
  let first: { State?: { Pid?: unknown; CgroupPath?: unknown } } | undefined
  try {
    const entries: unknown = JSON.parse(result.stdout)
    first = Array.isArray(entries) ? (entries[0] as typeof first) : undefined
  } catch {
    first = undefined
  }
  if (!first?.State) {
    throw new ContainerRunError('inspect', containerName, { ...result, stderr: `salida ilegible: «${result.stdout.trim()}»` })
  }
  const { Pid: pid, CgroupPath: cgroup } = first.State
  return {
    hostPids: typeof pid === 'number' && pid !== NOT_RUNNING_PID ? [pid] : [],
    ...(typeof cgroup === 'string' && cgroup !== '' ? { cgroup } : {}),
  }
}

/**
 * Crea y arranca el contenedor sin esperarlo: la materialización de una unidad
 * de vida larga. Es el único sitio del árbol que emite `create` y `start`.
 * Si `start` falla, el contenedor queda creado y el error nombra la etapa:
 * retirarlo es decisión de su dueño.
 */
export async function materializeContainer(podman: PodmanExecutor, spec: WorkerContainerSpec): Promise<MaterializedContainer> {
  const containerName = workerContainerName(spec.workerId)
  const created = await requireSuccess(podman, 'create', containerName, createWorkerContainerArgv(spec))
  await requireSuccess(podman, 'start', containerName, ['start', containerName])
  return { containerName, containerId: created.stdout.trim() }
}

type CompletedContainer = { containerId: string; exitCode: number }

/** Materializa y espera el contenedor; devuelve el id que imprimió `podman create` y el código de su proceso. */
async function runAndIdentify(podman: PodmanExecutor, spec: WorkerContainerSpec): Promise<CompletedContainer> {
  const { containerName, containerId } = await materializeContainer(podman, spec)
  const exitCode = parseWaitExitCode(containerName, await requireSuccess(podman, 'wait', containerName, ['wait', containerName]))
  return { containerId, exitCode }
}

/** Crea, arranca y espera el contenedor; devuelve el código de salida de su proceso. No lo retira. */
export async function runToCompletion(podman: PodmanExecutor, spec: WorkerContainerSpec): Promise<number> {
  return (await runAndIdentify(podman, spec)).exitCode
}

/**
 * El resultado de un trabajo: su veredicto y su diagnóstico, no sus datos.
 *
 * - `exitCode` es el veredicto del proceso principal.
 * - `stdout` y `stderr` son diagnóstico, cada uno de su flujo (medido con el
 *   driver `k8s-file`: `podman logs` no los mezcla). No son un canal de
 *   datos: lo que un trabajo produce lo escribe en un montaje declarado, y
 *   quien lo invoca lo lee de ahí.
 * - `containerName` nombra al contenedor que corrió, con las etiquetas de su
 *   dueño, para correlacionar el diagnóstico con su medida y su barrido.
 * - `containerId` es el id que imprimió `podman create`: el que nombra el
 *   cgroup `libpod-<id>` de cada proceso de la unidad.
 */
export type JobOutput = {
  exitCode: number
  stdout: string
  stderr: string
  containerName: string
  containerId: string
}

/**
 * Corre el contenedor hasta que termine y devuelve su veredicto y su
 * diagnóstico, leído con `podman logs` antes de retirarlo. La limpieza ocurre
 * siempre, también si una etapa falla.
 */
export async function runJobWithOutput(podman: PodmanExecutor, spec: WorkerContainerSpec): Promise<JobOutput> {
  const name = workerContainerName(spec.workerId)
  try {
    const { containerId, exitCode } = await runAndIdentify(podman, spec)
    const logs = await requireSuccess(podman, 'logs', name, ['logs', name])
    return { exitCode, stdout: logs.stdout, stderr: logs.stderr, containerName: name, containerId }
  } finally {
    await podman.run(removeWorkerContainerArgv(name))
  }
}

/** Envía `signal` al proceso principal del contenedor (p. ej. SIGTERM para un apagado ordenado). */
export async function signalContainer(podman: PodmanExecutor, name: string, signal: NodeJS.Signals): Promise<void> {
  await requireSuccess(podman, 'signal', name, ['kill', '--signal', signal, name])
}

/** Copia cada ruta del contenedor a `hostDir` con su nombre base; devuelve las rutas en el anfitrión. */
export async function exportArtifacts(
  podman: PodmanExecutor,
  name: string,
  containerPaths: readonly string[],
  hostDir: string,
): Promise<string[]> {
  const exported: string[] = []
  for (const containerPath of containerPaths) {
    const hostPath = join(hostDir, basename(containerPath))
    await requireSuccess(podman, 'export', `${name}:${containerPath}`, ['cp', `${name}:${containerPath}`, hostPath])
    exported.push(hostPath)
  }
  return exported
}

export type ArtifactRequest = {
  containerPaths: readonly string[]
  hostDir: string
}

export type JobOutcome = {
  exitCode: number
  artifacts: string[]
}

/**
 * Corre el contenedor hasta que termine, exporta lo pedido y sólo entonces
 * lo retira. La limpieza ocurre siempre —también si correr o exportar
 * falla— y nunca antes de la exportación.
 */
export async function runJobAndCollect(
  podman: PodmanExecutor,
  spec: WorkerContainerSpec,
  artifacts: ArtifactRequest,
): Promise<JobOutcome> {
  const name = workerContainerName(spec.workerId)
  try {
    const exitCode = await runToCompletion(podman, spec)
    const exported = await exportArtifacts(podman, name, artifacts.containerPaths, artifacts.hostDir)
    return { exitCode, artifacts: exported }
  } finally {
    await podman.run(removeWorkerContainerArgv(name))
  }
}

/**
 * Contrato del perfil de límites de recursos de un worker de Podman
 * (ADR-THYROX-007 Regla 2, TASK-THYROX-0615).
 *
 * Cada bandera que este módulo compone ya se midió contra su control en
 * `src/lib/podman_capabilities.sh` (`--pids-limit`, `--memory`, `--cpus`,
 * `--network none`, `--read-only`, montajes `:ro`). Aquí sólo vive el
 * CONTRATO del perfil —su validación y su traducción a argv—, nunca la
 * ejecución: el `PodmanWorkerManager` que crea y lanza contenedores es
 * trabajo futuro, no de este archivo.
 */

/**
 * `host` existe porque, medido en el contenedor remoto, el proxy de salida
 * escucha en el loopback del anfitrión (`127.0.0.1`) y ni `bridge` ni
 * `slirp4netns` lo alcanzan. Su costo: el trabajo ve TODO servicio del
 * loopback del anfitrión (Redis, Ollama, el proxy local). Por eso nunca es
 * el default y se declara sólo para trabajos sin credencial cuyo único
 * destino de red es el exterior.
 */
export type WorkerNetworkMode = 'none' | 'bridge' | 'host'
export type WorkerMountMode = 'ro' | 'rw'

export type WorkerResourceMount = {
  source: string
  destination: string
  mode: WorkerMountMode
}

export type WorkerResourceProfile = {
  cpus: number
  memoryMib: number
  pidsLimit: number
  network: WorkerNetworkMode
  readOnlyRootfs: boolean
  mounts: WorkerResourceMount[]
  /**
   * Variables del proceso del trabajo. Su valor queda en `Config.Env` de
   * `podman inspect` (medido 2026-09-29, `repositoryJobProfile.ts`), así que
   * sólo admite valores públicos: un nombre de credencial se rehúsa.
   */
  environment?: Readonly<Record<string, string>>
  /**
   * Puertos del contenedor publicados en el anfitrión. Sólo en loopback
   * (`127.0.0.1`): un servicio de un worker nunca escucha en la red del
   * anfitrión. Se emiten como `-p 127.0.0.1:<host>:<contenedor>`.
   */
  publishedPorts?: readonly WorkerPublishedPort[]
  /**
   * Dispositivos concedidos, en forma CDI (`nvidia.com/gpu=<uuid>`). Una ruta
   * de `/dev` se rehúsa: el dispositivo lo nombra el grant, no el anfitrión.
   */
  devices?: readonly string[]
}

export type WorkerPublishedPort = {
  hostAddress: '127.0.0.1'
  hostPort: number
  containerPort: number
}

const KNOWN_NETWORK_MODES: readonly WorkerNetworkMode[] = ['none', 'bridge', 'host']
const ENVIRONMENT_NAME_PATTERN = /^[A-Za-z_][A-Za-z0-9_]*$/
const CREDENTIAL_NAME_PATTERN = /(TOKEN|SECRET|PASSWORD|PASSWD|KEY|CREDENTIAL)/i
const KNOWN_MOUNT_MODES: readonly WorkerMountMode[] = ['ro', 'rw']
const LOOPBACK_HOST_ADDRESS = '127.0.0.1'
const MIN_PORT = 1
const MAX_PORT = 65_535
/** La red que publica puertos: `none` no tiene a dónde y `host` no lo necesita. */
const PORT_PUBLISHING_NETWORK: WorkerNetworkMode = 'bridge'
/** Nombre CDI de un dispositivo: `<vendor>/<clase>=<nombre>` (`nvidia.com/gpu=<uuid>`). */
const CDI_DEVICE_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]*\/[A-Za-z0-9][A-Za-z0-9._-]*=[A-Za-z0-9][A-Za-z0-9._:-]*$/

/**
 * El perfil más restrictivo medido: sin red, rootfs de sólo lectura, sin
 * montajes declarados. Relajar cualquiera de los tres es explícito en el
 * perfil que se declare — nunca el default silencioso.
 */
export const DEFAULT_WORKER_RESOURCE_PROFILE: WorkerResourceProfile = {
  cpus: 1,
  memoryMib: 1024,
  pidsLimit: 128,
  network: 'none',
  readOnlyRootfs: true,
  mounts: [],
}

/** Un campo del perfil no pasó su validación; nombra el campo, nunca lo omite en silencio. */
export class InvalidWorkerResourceProfileError extends Error {
  readonly field: string

  constructor(field: string, message: string) {
    super(message)
    this.name = 'InvalidWorkerResourceProfileError'
    this.field = field
  }
}

function requirePositiveNumber(field: string, value: number): void {
  if (!Number.isFinite(value) || value <= 0) {
    throw new InvalidWorkerResourceProfileError(field, `${field} debe ser un número > 0, recibido: ${value}`)
  }
}

function requirePositiveInteger(field: string, value: number): void {
  if (!Number.isInteger(value) || value < 1) {
    throw new InvalidWorkerResourceProfileError(field, `${field} debe ser un entero >= 1, recibido: ${value}`)
  }
}

function requireKnownNetwork(network: WorkerNetworkMode): void {
  if (!KNOWN_NETWORK_MODES.includes(network)) {
    throw new InvalidWorkerResourceProfileError('network', `red desconocida: ${network}`)
  }
}

function requireValidMount(mount: WorkerResourceMount, index: number): void {
  const field = `mounts[${index}]`
  if (!mount.source) {
    throw new InvalidWorkerResourceProfileError(`${field}.source`, 'el origen del montaje no puede estar vacío')
  }
  if (!mount.destination.startsWith('/')) {
    throw new InvalidWorkerResourceProfileError(
      `${field}.destination`,
      `el destino del montaje debe ser una ruta absoluta, recibido: ${mount.destination}`,
    )
  }
  if (!KNOWN_MOUNT_MODES.includes(mount.mode)) {
    throw new InvalidWorkerResourceProfileError(`${field}.mode`, `modo de montaje desconocido: ${mount.mode}`)
  }
}

/** Valida el perfil completo; rehúsa en el primer campo inválido, nombrándolo. */
export function validateWorkerResourceProfile(profile: WorkerResourceProfile): void {
  requirePositiveNumber('cpus', profile.cpus)
  requirePositiveNumber('memoryMib', profile.memoryMib)
  requirePositiveInteger('pidsLimit', profile.pidsLimit)
  requireKnownNetwork(profile.network)
  profile.mounts.forEach((mount, index) => requireValidMount(mount, index))
  Object.keys(profile.environment ?? {}).forEach(requirePublicEnvironmentName)
  requireValidPublishedPorts(profile)
  profile.devices?.forEach(requireCdiDevice)
}

function isValidPort(port: number): boolean {
  return Number.isInteger(port) && port >= MIN_PORT && port <= MAX_PORT
}

function requireValidPublishedPorts(profile: WorkerResourceProfile): void {
  const ports = profile.publishedPorts ?? []
  if (ports.length > 0 && profile.network !== PORT_PUBLISHING_NETWORK) {
    throw new InvalidWorkerResourceProfileError(
      'publishedPorts',
      `publicar puertos exige red ${PORT_PUBLISHING_NETWORK}, el perfil declara ${profile.network}`,
    )
  }
  ports.forEach(requireValidPublishedPort)
}

function requireValidPublishedPort(port: WorkerPublishedPort, index: number): void {
  const field = `publishedPorts.${index}`
  if (port.hostAddress !== LOOPBACK_HOST_ADDRESS) {
    throw new InvalidWorkerResourceProfileError(`${field}.hostAddress`, `sólo se publica en ${LOOPBACK_HOST_ADDRESS}, recibido: ${port.hostAddress}`)
  }
  if (!isValidPort(port.hostPort)) {
    throw new InvalidWorkerResourceProfileError(`${field}.hostPort`, `puerto fuera de ${MIN_PORT}–${MAX_PORT}: ${port.hostPort}`)
  }
  if (!isValidPort(port.containerPort)) {
    throw new InvalidWorkerResourceProfileError(`${field}.containerPort`, `puerto fuera de ${MIN_PORT}–${MAX_PORT}: ${port.containerPort}`)
  }
}

function requireCdiDevice(device: string, index: number): void {
  if (!CDI_DEVICE_PATTERN.test(device)) {
    throw new InvalidWorkerResourceProfileError(`devices.${index}`, `el dispositivo debe ir en forma CDI <vendor>/<clase>=<nombre>, recibido: ${device}`)
  }
}

function requirePublicEnvironmentName(name: string): void {
  const field = `environment.${name}`
  if (!ENVIRONMENT_NAME_PATTERN.test(name)) {
    throw new InvalidWorkerResourceProfileError(field, `nombre de variable inválido: ${name}`)
  }
  if (CREDENTIAL_NAME_PATTERN.test(name)) {
    throw new InvalidWorkerResourceProfileError(field, `${name} nombra una credencial y su valor quedaría en podman inspect`)
  }
}

function cpuLimitArgv(cpus: number): string[] {
  return ['--cpus', String(cpus)]
}

function memoryLimitArgv(memoryMib: number): string[] {
  return ['--memory', `${memoryMib}m`]
}

function pidsLimitArgv(pidsLimit: number): string[] {
  return ['--pids-limit', String(pidsLimit)]
}

function networkArgv(network: WorkerNetworkMode): string[] {
  return ['--network', network]
}

function rootfsArgv(readOnlyRootfs: boolean): string[] {
  return readOnlyRootfs ? ['--read-only', '--read-only-tmpfs=false'] : []
}

function environmentArgv(environment: Readonly<Record<string, string>>): string[] {
  return Object.keys(environment).sort().flatMap(name => ['--env', `${name}=${environment[name]}`])
}

function publishedPortArgv(port: WorkerPublishedPort): string[] {
  return ['-p', `${port.hostAddress}:${port.hostPort}:${port.containerPort}`]
}

function deviceArgv(device: string): string[] {
  return ['--device', device]
}

function mountArgv(mount: WorkerResourceMount): string[] {
  return ['-v', `${mount.source}:${mount.destination}:${mount.mode}`]
}

/**
 * Traduce un perfil validado al argv de límites para `podman create`/`run`
 * — no ejecuta nada, sólo compone el argv (mismo contrato que
 * `thyrox_infrastructure_create_argv` en `src/lib/infrastructure.sh`: un
 * perfil inválido rehúsa antes de emitir ningún argumento).
 */
export function workerResourceLimitArgv(profile: WorkerResourceProfile): string[] {
  validateWorkerResourceProfile(profile)
  return [
    ...cpuLimitArgv(profile.cpus),
    ...memoryLimitArgv(profile.memoryMib),
    ...pidsLimitArgv(profile.pidsLimit),
    ...networkArgv(profile.network),
    ...rootfsArgv(profile.readOnlyRootfs),
    ...profile.mounts.flatMap(mountArgv),
    ...environmentArgv(profile.environment ?? {}),
    ...(profile.publishedPorts ?? []).flatMap(publishedPortArgv),
    ...(profile.devices ?? []).flatMap(deviceArgv),
  ]
}

/**
 * Ciclo de vida de un contenedor de worker de Podman (ADR-THYROX-007
 * Regla 2, TASK-THYROX-0616; dueño neutral desde TASK-THYROX-0667): crear,
 * inspeccionar, detener y retirar un contenedor, garantizar que ningún
 * contenedor ni proceso sobrevive a su worker, y encontrar huérfanos.
 *
 * Implementación compartida ≠ dueño compartido (ADR-007, «Mecanismo
 * compartido, dueños distintos»). Cada contenedor lleva su dueño en tres
 * etiquetas —tipo (`daemon` | `pool` | `lab` | `model-coordinator` | `infrastructure`), identificador y PID— y qué es un
 * huérfano NO lo decide este módulo: el dueño entrega su predicado. Así el
 * daemon conserva su política (daemon muerto ⇒ huérfano) sin que el barrido
 * de un dueño retire nunca lo de otro.
 *
 * El estado que reporta Podman NO es evidencia de vida —TASK-THYROX-0605
 * midió `running` con el proceso ya muerto tras `podman start`—, así que
 * toda decisión de vivacidad pasa por el PID real (`isProcessAlive`
 * inyectado), nunca sólo por `.State.Status`.
 */

import type { PodmanCommandResult, PodmanExecutor } from './podmanExecutor.js'

/** Prefijo de nombre de todo contenedor de worker que este módulo crea o reconoce como propio. */
export const WORKER_CONTAINER_NAME_PREFIX = 'thyrox-worker-'

export function workerContainerName(workerId: string): string {
  return `${WORKER_CONTAINER_NAME_PREFIX}${workerId}`
}

/** Etiquetas del dueño: su tipo, su identificador y el PID que su política de huérfanos consulta. */
export const OWNER_KIND_LABEL_KEY = 'thyrox.owner-kind'
export const OWNER_ID_LABEL_KEY = 'thyrox.owner-id'
export const OWNER_PID_LABEL_KEY = 'thyrox.owner-pid'
/** Etiqueta con el identificador de worker — permite recuperarlo desde un `podman inspect`, sin estado propio. */
export const WORKER_ID_LABEL_KEY = 'thyrox.worker-id'

/** Plazo por defecto de `podman stop` antes de que Podman escale a SIGKILL. */
export const DEFAULT_STOP_TIMEOUT_SECONDS = 10

export type ContainerOwnerKind = 'daemon' | 'pool' | 'lab' | 'model-coordinator' | 'infrastructure' | 'task'

const OWNER_KINDS: readonly ContainerOwnerKind[] = ['daemon', 'pool', 'lab', 'model-coordinator', 'infrastructure', 'task']
const SAFE_IDENTIFIER_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_.-]*$/
/** Una clave de etiqueta propia: no vacía y sin espacios ni `=`. */
const LABEL_KEY_PATTERN = /^[^\s=]+$/
/** Prefijo común de las etiquetas de dueño, reservadas a este módulo. */
const OWNER_LABEL_KEY_PREFIX = 'thyrox.owner-'
/** Valor que `podman inspect` imprime para una etiqueta que el contenedor no lleva. */
const MISSING_LABEL_VALUE = '<no value>'

export type ContainerOwner = {
  kind: ContainerOwnerKind
  id: string
  pid: number
}

/** Un campo del spec no pasó su validación; nombra el campo, nunca lo omite en silencio. */
export class InvalidWorkerContainerSpecError extends Error {
  readonly field: string

  constructor(field: string, message: string) {
    super(message)
    this.name = 'InvalidWorkerContainerSpecError'
    this.field = field
  }
}

export type WorkerContainerSpec = {
  workerId: string
  image: string
  owner: ContainerOwner
  /** Argv de límites ya compuesto por `workerResourceProfile.ts`/`repositoryJobProfile.ts`. */
  resourceArgv: readonly string[]
  command?: readonly string[]
  /**
   * Etiquetas propias del dueño, además de las de dueño y worker; no pueden
   * reescribir ninguna de `thyrox.owner-*` ni `thyrox.worker-id`.
   */
  labels?: Readonly<Record<string, string>>
}

function isOwnerKind(value: string): value is ContainerOwnerKind {
  return (OWNER_KINDS as readonly string[]).includes(value)
}

function isPositiveInteger(value: number): boolean {
  return Number.isInteger(value) && value > 0
}

function requireSafeIdentifier(field: string, value: string): void {
  if (!SAFE_IDENTIFIER_PATTERN.test(value)) {
    throw new InvalidWorkerContainerSpecError(field, `${field} inválido: ${value}`)
  }
}

function requireNonEmptyImage(image: string): void {
  if (!image) {
    throw new InvalidWorkerContainerSpecError('image', 'la imagen no puede estar vacía')
  }
}

/**
 * El dueño que las etiquetas de un contenedor declaran, leído por las mismas
 * claves con que `ownerLabelArgv` lo escribe; `undefined` si falta alguna o
 * no es válida. Quien reconstruye desde Podman no inventa un dueño.
 */
export function ownerFromLabels(labels: Readonly<Record<string, unknown>> | null | undefined): ContainerOwner | undefined {
  const kind = labels?.[OWNER_KIND_LABEL_KEY]
  const id = labels?.[OWNER_ID_LABEL_KEY]
  const pid = Number(labels?.[OWNER_PID_LABEL_KEY])
  if (typeof kind !== 'string' || typeof id !== 'string' || !isOwnerKind(kind)) return undefined
  const owner: ContainerOwner = { kind, id, pid }
  try {
    requireValidOwner(owner)
  } catch {
    return undefined
  }
  return owner
}

export function requireValidOwner(owner: ContainerOwner): void {
  if (!isOwnerKind(owner.kind)) {
    throw new InvalidWorkerContainerSpecError('owner.kind', `tipo de dueño desconocido: ${owner.kind}`)
  }
  requireSafeIdentifier('owner.id', owner.id)
  if (!isPositiveInteger(owner.pid)) {
    throw new InvalidWorkerContainerSpecError('owner.pid', `owner.pid debe ser un entero > 0, recibido: ${owner.pid}`)
  }
}

/** Valida el spec completo; rehúsa en el primer campo inválido, nombrándolo. */
export function validateWorkerContainerSpec(spec: WorkerContainerSpec): void {
  requireSafeIdentifier('workerId', spec.workerId)
  requireNonEmptyImage(spec.image)
  requireValidOwner(spec.owner)
  Object.keys(spec.labels ?? {}).forEach(requireOwnLabelKey)
}

function isReservedLabelKey(key: string): boolean {
  return key.startsWith(OWNER_LABEL_KEY_PREFIX) || key === WORKER_ID_LABEL_KEY
}

function requireOwnLabelKey(key: string): void {
  const field = `labels.${key}`
  if (!LABEL_KEY_PATTERN.test(key)) {
    throw new InvalidWorkerContainerSpecError(field, `clave de etiqueta inválida: «${key}»`)
  }
  if (isReservedLabelKey(key)) {
    throw new InvalidWorkerContainerSpecError(field, `${key} es una etiqueta de dueño o worker y no se reescribe`)
  }
}

function labelArgv(key: string, value: string): string[] {
  return ['--label', `${key}=${value}`]
}

export function ownerLabelArgv(owner: ContainerOwner): string[] {
  return [
    ...labelArgv(OWNER_KIND_LABEL_KEY, owner.kind),
    ...labelArgv(OWNER_ID_LABEL_KEY, owner.id),
    ...labelArgv(OWNER_PID_LABEL_KEY, String(owner.pid)),
  ]
}

function ownLabelArgv(labels: Readonly<Record<string, string>>): string[] {
  return Object.keys(labels).sort().flatMap(key => labelArgv(key, labels[key] as string))
}

/**
 * Traduce un spec validado al argv de `podman create` — nombre, etiquetas de
 * dueño y worker, etiquetas propias del dueño, límites e imagen.
 */
export function createWorkerContainerArgv(spec: WorkerContainerSpec): string[] {
  validateWorkerContainerSpec(spec)
  return [
    'create',
    '--name', workerContainerName(spec.workerId),
    ...ownerLabelArgv(spec.owner),
    ...labelArgv(WORKER_ID_LABEL_KEY, spec.workerId),
    ...ownLabelArgv(spec.labels ?? {}),
    ...spec.resourceArgv,
    spec.image,
    ...(spec.command ?? []),
  ]
}

function labelField(key: string): string {
  return `{{index .Config.Labels "${key}"}}`
}

/**
 * Formato de `podman inspect`: status, PID y las cuatro etiquetas propias
 * en una sola invocación — el mismo `{{.State.Status}}\t{{.State.Pid}}` que
 * `src/lib/infrastructure.sh`, extendido con lo que el barrido necesita.
 */
const INSPECT_FORMAT = [
  '{{.State.Status}}',
  '{{.State.Pid}}',
  labelField(OWNER_KIND_LABEL_KEY),
  labelField(OWNER_ID_LABEL_KEY),
  labelField(OWNER_PID_LABEL_KEY),
  labelField(WORKER_ID_LABEL_KEY),
].join('\t')

export function inspectWorkerContainerArgv(name: string): string[] {
  return ['inspect', '--format', INSPECT_FORMAT, name]
}

export function stopWorkerContainerArgv(name: string, timeoutSeconds: number): string[] {
  return ['stop', '--time', String(timeoutSeconds), name]
}

/** Siempre fuerza el retiro: un contenedor no queda a medio retirar por depender de que ya esté detenido. */
export function removeWorkerContainerArgv(name: string): string[] {
  return ['rm', '--force', name]
}

/** Lista, por nombre, todo contenedor gestionado por este módulo, de cualquier dueño. */
export function listWorkerContainerNamesArgv(): string[] {
  return ['ps', '--all', '--filter', `name=^${WORKER_CONTAINER_NAME_PREFIX}`, '--format', '{{.Names}}']
}

/** El dueño tal como lo leen las etiquetas: cada campo es `null` si falta o no es válido. */
export type InspectedOwner = {
  kind: ContainerOwnerKind | null
  id: string | null
  pid: number | null
}

export type PresentWorkerContainer = {
  present: true
  status: string
  pid: number
  owner: InspectedOwner
  workerId: string | null
}

export type WorkerContainerInspection = { present: false } | PresentWorkerContainer

function parseLabelPid(raw: string): number | null {
  const parsed = Number(raw)
  return isPositiveInteger(parsed) ? parsed : null
}

function parseLabelText(raw: string): string | null {
  return raw === '' || raw === MISSING_LABEL_VALUE ? null : raw
}

function parseOwnerKind(raw: string): ContainerOwnerKind | null {
  return isOwnerKind(raw) ? raw : null
}

/** Traduce la salida de `inspectWorkerContainerArgv` — ausente (exit != 0) o presente con sus campos. */
export function parseWorkerContainerInspection(result: PodmanCommandResult): WorkerContainerInspection {
  if (result.exitCode !== 0) return { present: false }
  const [status, pidRaw, kindRaw, idRaw, ownerPidRaw, workerIdRaw] = result.stdout.trim().split('\t')
  return {
    present: true,
    status: status ?? '',
    pid: Number(pidRaw) || 0,
    owner: {
      kind: parseOwnerKind(kindRaw ?? ''),
      id: parseLabelText(idRaw ?? ''),
      pid: parseLabelPid(ownerPidRaw ?? ''),
    },
    workerId: parseLabelText(workerIdRaw ?? ''),
  }
}

function parseContainerNameList(stdout: string): string[] {
  return stdout
    .split('\n')
    .map(line => line.trim())
    .filter(line => line.length > 0)
}

/**
 * La regla que TASK-THYROX-0605 obligó a nombrar: un contenedor `running`
 * con el PID muerto NO está vivo. `present`/`status`/`pid` solos nunca
 * bastan — la sonda de PID es la que decide.
 */
export function isWorkerContainerProcessAlive(
  inspection: WorkerContainerInspection,
  checkProcessAlive: (pid: number) => boolean,
): boolean {
  return inspection.present && inspection.status === 'running' && inspection.pid > 0 && checkProcessAlive(inspection.pid)
}

/** La política de huérfanos de un dueño: recibe un contenedor presente y decide si le toca retirarlo. */
export type OrphanPredicate = (inspection: PresentWorkerContainer) => boolean

export interface WorkerContainerLifecycleDeps {
  podman: PodmanExecutor
  /** Inyectado — nunca se asume vivo por el status de Podman; ver `isWorkerContainerProcessAlive`. */
  isProcessAlive: (pid: number) => boolean
  /** Señal directa de última instancia cuando el PID sigue vivo tras `stop`+`rm` (estado stale de Podman). */
  killProcess: (pid: number, signal: NodeJS.Signals) => void
}

/** Deps reales con la sonda de vida que el dueño aporta, y `process.kill` como señal directa. */
export function createWorkerContainerLifecycleDeps(
  podman: PodmanExecutor,
  isProcessAlive: (pid: number) => boolean,
): WorkerContainerLifecycleDeps {
  return {
    podman,
    isProcessAlive,
    killProcess: (pid, signal) => process.kill(pid, signal),
  }
}

/** Crea el contenedor y lo arranca; si el `create` falla, nunca se intenta el `start`. */
export async function createWorkerContainer(
  deps: WorkerContainerLifecycleDeps,
  spec: WorkerContainerSpec,
): Promise<PodmanCommandResult> {
  const created = await deps.podman.run(createWorkerContainerArgv(spec))
  if (created.exitCode !== 0) return created
  return deps.podman.run(['start', workerContainerName(spec.workerId)])
}

export async function inspectWorkerContainer(
  deps: Pick<WorkerContainerLifecycleDeps, 'podman'>,
  name: string,
): Promise<WorkerContainerInspection> {
  return parseWorkerContainerInspection(await deps.podman.run(inspectWorkerContainerArgv(name)))
}

export async function stopWorkerContainer(
  deps: Pick<WorkerContainerLifecycleDeps, 'podman'>,
  name: string,
  timeoutSeconds: number,
): Promise<PodmanCommandResult> {
  return deps.podman.run(stopWorkerContainerArgv(name, timeoutSeconds))
}

export async function removeWorkerContainer(
  deps: Pick<WorkerContainerLifecycleDeps, 'podman'>,
  name: string,
): Promise<PodmanCommandResult> {
  return deps.podman.run(removeWorkerContainerArgv(name))
}

export type WorkerContainerRetirement = {
  name: string
  stopped: boolean
  removed: boolean
  /** `true` si, tras `stop`+`rm`, el PID seguía vivo y hubo que matarlo directo (estado stale de Podman). */
  killedStaleProcess: boolean
}

/** Envía SIGKILL directo si, tras `stop`+`rm`, el PID inspeccionado sigue vivo — la garantía de «nada sobrevive». */
function killStaleProcessIfAlive(deps: WorkerContainerLifecycleDeps, inspection: WorkerContainerInspection): boolean {
  if (!inspection.present || inspection.pid <= 0) return false
  if (!deps.isProcessAlive(inspection.pid)) return false
  deps.killProcess(inspection.pid, 'SIGKILL')
  return true
}

/**
 * Detiene y retira un contenedor por su nombre, y verifica al final —sobre
 * el PID, no sobre lo que Podman reportó— que no quedó un proceso vivo. Un
 * contenedor ya ausente no invoca ni `stop` ni `rm`.
 */
export async function retireWorkerContainer(
  deps: WorkerContainerLifecycleDeps,
  name: string,
  timeoutSeconds: number = DEFAULT_STOP_TIMEOUT_SECONDS,
): Promise<WorkerContainerRetirement> {
  const inspection = await inspectWorkerContainer(deps, name)
  if (!inspection.present) {
    return { name, stopped: false, removed: false, killedStaleProcess: false }
  }
  const stopResult = await stopWorkerContainer(deps, name, timeoutSeconds)
  const removeResult = await removeWorkerContainer(deps, name)
  return {
    name,
    stopped: stopResult.exitCode === 0,
    removed: removeResult.exitCode === 0,
    killedStaleProcess: killStaleProcessIfAlive(deps, inspection),
  }
}

export type OrphanedWorkerContainer = {
  name: string
  workerId: string | null
  owner: InspectedOwner
}

/** Encuentra, sin retirar nada, los contenedores gestionados que el predicado del dueño marca como huérfanos. */
export async function findOrphanedWorkerContainers(
  deps: WorkerContainerLifecycleDeps,
  isOrphan: OrphanPredicate,
): Promise<OrphanedWorkerContainer[]> {
  const listing = await deps.podman.run(listWorkerContainerNamesArgv())
  const orphans: OrphanedWorkerContainer[] = []
  for (const name of parseContainerNameList(listing.stdout)) {
    const inspection = await inspectWorkerContainer(deps, name)
    if (!inspection.present || !isOrphan(inspection)) continue
    orphans.push({ name, workerId: inspection.workerId, owner: inspection.owner })
  }
  return orphans
}

/** Encuentra y retira, uno por uno, los huérfanos que el predicado del dueño marca. */
export async function retireOrphanedWorkerContainers(
  deps: WorkerContainerLifecycleDeps,
  isOrphan: OrphanPredicate,
  timeoutSeconds: number = DEFAULT_STOP_TIMEOUT_SECONDS,
): Promise<WorkerContainerRetirement[]> {
  const orphans = await findOrphanedWorkerContainers(deps, isOrphan)
  const retirements: WorkerContainerRetirement[] = []
  for (const orphan of orphans) {
    retirements.push(await retireWorkerContainer(deps, orphan.name, timeoutSeconds))
  }
  return retirements
}

/**
 * La verificación de un artefacto publicado, ejecutada como trabajo de la
 * primitiva de Podman (ADR-THYROX-007, TASK-THYROX-0728).
 *
 * El trabajo prueba lo que un consumidor externo vería: no monta el
 * almacenamiento de Podman de esta sesión ni recibe credencial alguna. Lee
 * el registry de forma anónima, materializa cada blob en su montaje de
 * trabajo y deja su veredicto en `verification.json` de ese montaje: la
 * salida estándar del contenedor es diagnóstico, no canal de datos.
 *
 * El intérprete se monta de sólo lectura desde el anfitrión, igual que el
 * repositorio, así que la imagen sólo aporta la libc. La composición pasa por
 * la autorización canónica (`registry-operation`, con la cita de su tarea):
 * el verificador no compone por spec ni alcanza ninguna función interna de la
 * primitiva.
 */
import { mkdir, readFile, rm } from 'node:fs/promises'
import { join } from 'node:path'

import { runExecution, type ExecutionAuthorization } from '@thyrox/podman-execution/executionAuthorization.ts'
import type { PodmanExecutor } from '@thyrox/podman-execution/podmanExecutor.ts'
import type { ContainerOwner } from '@thyrox/podman-execution/workerContainerLifecycle.ts'
import type { WorkerResourceProfile } from '@thyrox/podman-execution/workerResourceProfile.ts'

import type { ArtifactLocation, PinnedArtifact } from './artifactRegistry.js'
import type { ArtifactVerifier, VerificationOutcome } from './artifactVerifier.js'
import { jobNetworkProfile, type JobEgress } from './jobEgress.js'

export const VERIFICATION_REPORT_NAME = 'verification.json'

/** La cita de la tarea que autoriza la operación de registry; el llamador puede declarar otra. */
export const DEFAULT_VERIFICATION_TASK_CITATION = 'TASK-THYROX-0728'

const CONTAINER_BUN = '/usr/local/bin/bun'
const CONTAINER_REPOSITORY = '/w'
const CONTAINER_SCRATCH = '/scratch'
const VERIFY_ENTRY = `${CONTAINER_REPOSITORY}/src/packages/artifact-registry/bin/verifyArtifact.ts`

export interface PodmanJobVerifierOptions {
  readonly podman: PodmanExecutor
  /** Imagen del trabajo, ya resuelta a un ID o digest inmutable. */
  readonly image: string
  readonly bunPath: string
  readonly repositoryRoot: string
  /** Directorio del anfitrión donde el trabajo materializa blobs; su disco lo admitió el llamador. */
  readonly scratchDir: string
  readonly registryUrl: string
  readonly egress: JobEgress
  readonly owner: ContainerOwner
  readonly workerId: string
  readonly limits: Pick<WorkerResourceProfile, 'cpus' | 'memoryMib' | 'pidsLimit'>
  /** Cita de la tarea que autoriza la verificación; por defecto, la del flujo que la define. */
  readonly taskCitation?: string
}

/**
 * La verificación compuesta en la autorización canónica: clase
 * `registry-operation` con la cita de su tarea, la red que decide el egress y
 * los montajes de siempre —intérprete y repositorio de sólo lectura, scratch
 * de escritura—.
 */
export function verificationAuthorization(options: PodmanJobVerifierOptions, pinned: PinnedArtifact, location: ArtifactLocation): ExecutionAuthorization {
  const network = jobNetworkProfile(options.egress)
  return {
    executionId: options.workerId,
    reference: { kind: 'task', citation: options.taskCitation ?? DEFAULT_VERIFICATION_TASK_CITATION },
    owner: options.owner,
    kind: 'registry-operation',
    image: options.image,
    command: [
      CONTAINER_BUN, VERIFY_ENTRY,
      '--registry', options.registryUrl,
      '--repository', location.repository,
      '--tag', location.tag,
      '--digest', pinned.digest,
      '--work-dir', `${CONTAINER_SCRATCH}/blobs`,
      '--report', `${CONTAINER_SCRATCH}/${VERIFICATION_REPORT_NAME}`,
    ],
    mounts: [
      { source: options.bunPath, destination: CONTAINER_BUN, mode: 'ro' },
      { source: options.repositoryRoot, destination: CONTAINER_REPOSITORY, mode: 'ro' },
      { source: options.scratchDir, destination: CONTAINER_SCRATCH, mode: 'rw' },
      ...network.mounts,
    ],
    resources: options.limits,
    network: network.network,
    environment: { ...network.environment, HOME: `${CONTAINER_SCRATCH}/home`, TMPDIR: `${CONTAINER_SCRATCH}/tmp` },
  }
}

async function readReport(path: string): Promise<VerificationOutcome | undefined> {
  try {
    return JSON.parse(await readFile(path, 'utf8')) as VerificationOutcome
  } catch {
    return undefined
  }
}

export function createPodmanJobVerifier(options: PodmanJobVerifierOptions): ArtifactVerifier {
  return {
    async verify(pinned, location) {
      await rm(options.scratchDir, { recursive: true, force: true })
      await Promise.all(['home', 'tmp'].map(name => mkdir(join(options.scratchDir, name), { recursive: true })))
      try {
        const job = await runExecution(options.podman, verificationAuthorization(options, pinned, location))
        const report = await readReport(join(options.scratchDir, VERIFICATION_REPORT_NAME))
        if (report) return report
        return {
          status: 'unverified',
          result: { status: 'job_failed', exitCode: job.exitCode, detail: `${job.containerName} no dejó veredicto: ${job.stderr.trim().slice(-400)}` },
        }
      } finally {
        await rm(options.scratchDir, { recursive: true, force: true })
      }
    },
  }
}

